INSERT INTO public.cases (id,title,teaser,specialty,organ_system,topic,year_level,difficulty,clinical_setting,estimated_minutes,xp_reward,mode,is_weekly_challenge,challenge_start,challenge_end,completions_count,patient,initial_presentation,history_categories,examinations,investigations,interpretation_task,differential_prompt,diagnosis_options,correct_diagnosis,correct_differentials,management_options,communication_task,outcomes,debrief,answer_key) VALUES
('11111111-1111-4111-8111-111111111111','A breathless patient in the emergency unit','A 62-year-old market trader can''t lie flat and is fighting for breath.','Internal Medicine','Cardiovascular','Heart failure',4,'medium','ED',20,150,'both',true,now()-interval '2 days',now()+interval '5 days',128,
'{"name":"Jean-Baptiste K.","age":62,"sex":"Male","location":"Kigali"}',
'Jean-Baptiste, 62, is brought to the emergency unit by his daughter. He has been increasingly short of breath for 5 days and woke tonight gasping. He is sitting upright, speaking in short sentences.',
'[{"category":"Presenting complaint","questions":[{"id":"h1","q":"When did the breathlessness start?","a":"Slowly over 5 days, much worse tonight. I woke up gasping."},{"id":"h2","q":"Can you lie flat?","a":"No, I sleep on three pillows now, sometimes in the chair."},{"id":"h3","q":"Any chest pain?","a":"A tight feeling, but no sharp pain."}]},{"category":"Past history","questions":[{"id":"h4","q":"Any long-term conditions?","a":"High blood pressure for 10 years. I stopped my tablets 3 months ago."},{"id":"h5","q":"Any heart problems before?","a":"The doctor said my heart was big two years ago."}]},{"category":"Social & drugs","questions":[{"id":"h6","q":"Do you smoke or drink?","a":"I stopped smoking 5 years ago. A little beer at weekends."},{"id":"h7","q":"Any leg swelling?","a":"Yes, my ankles are swollen, my shoes feel tight."},{"id":"h8","q":"Any fever or cough with sputum?","a":"No fever. A cough with frothy, slightly pink spit."}]}]',
'[{"id":"e1","name":"Vital signs","finding":"HR 118 irregular, BP 178/102, RR 30, SpO2 86% on air, T 36.8°C"},{"id":"e2","name":"Chest auscultation","finding":"Bilateral fine crackles to the mid zones. No bronchial breathing."},{"id":"e3","name":"Cardiovascular exam","finding":"Raised JVP 6 cm, displaced apex beat, S3 gallop."},{"id":"e4","name":"Legs","finding":"Pitting oedema to mid-shin bilaterally."}]',
'[{"id":"i1","name":"ECG","result":"Atrial fibrillation, rate 120, left ventricular hypertrophy. No ST elevation."},{"id":"i2","name":"Chest X-ray","result":"Cardiomegaly, upper lobe diversion, bilateral alveolar shadowing, small effusions."},{"id":"i3","name":"Echocardiogram (bedside)","result":"Dilated left ventricle, ejection fraction about 30%."},{"id":"i4","name":"Kidney function & electrolytes","result":"Creatinine 118 µmol/L, K 4.2 mmol/L, Na 134 mmol/L."},{"id":"i5","name":"Malaria rapid test","result":"Negative."},{"id":"i6","name":"CT pulmonary angiogram","result":"No pulmonary embolism."}]',
'{"prompt":"Look at the chest X-ray report. What is the most likely cause of the shadowing?","investigation":"Chest X-ray","options":["Pulmonary oedema","Lobar pneumonia","Tuberculosis","Pneumothorax"]}',
'List your top three differential diagnoses for this patient.',
ARRAY['Acute decompensated heart failure','Community-acquired pneumonia','Pulmonary embolism','Acute coronary syndrome','Pulmonary tuberculosis'],
'Acute decompensated heart failure',ARRAY['Acute decompensated heart failure','Acute coronary syndrome','Community-acquired pneumonia'],
'[{"id":"m1","label":"Sit upright and give oxygen to target SpO2 94–98%"},{"id":"m2","label":"IV furosemide 40–80 mg"},{"id":"m3","label":"Sublingual/IV nitrate while BP is high"},{"id":"m4","label":"Give 2 litres of IV fluid quickly"},{"id":"m5","label":"Start broad-spectrum antibiotics only"},{"id":"m6","label":"Anticoagulation plan and rate control for AF"}]',
'{"prompt":"His daughter asks: \"Is my father going to die? Is this because he stopped his tablets?\" What do you say?","options":[{"id":"c1","text":"\"Yes, stopping his tablets caused this. He should have known better.\""},{"id":"c2","text":"\"He is very unwell, but we are treating the fluid on his lungs now. Stopping his tablets may have contributed — we will help him restart safely and explain everything.\""},{"id":"c3","text":"\"Don''t worry, he will be fine by tomorrow.\""}]}',
'{"good":"His breathing eases within an hour and SpO2 rises to 95%. He is admitted to the medical ward and restarted on heart failure medicines.","partial":"He improves slowly but needs a longer stay and closer monitoring.","poor":"His breathing worsens and he needs transfer to high dependency care."}',
'{"summary":"Acute decompensated heart failure triggered by stopping antihypertensives and new atrial fibrillation.","teaching_points":["Orthopnoea, PND, raised JVP, crackles and oedema point to fluid overload.","Treat with upright position, oxygen, IV loop diuretic and nitrates if BP allows.","Look for the trigger: missed medicines, arrhythmia, ischaemia, infection."],"pitfalls":["Giving IV fluids to a breathless patient with pulmonary oedema.","Ordering CT for everyone before basic ECG and chest X-ray."]}',
'{"key_history":["h1","h2","h4","h7","h8"],"key_exams":["e1","e2","e3","e4"],"key_investigations":["i1","i2","i3","i4"],"unnecessary_investigations":["i6"],"interpretation":"Pulmonary oedema","management_correct":["m1","m2","m3","m6"],"management_harmful":["m4"],"communication_best":"c2"}'),
('22222222-2222-4222-8222-222222222222','A drowsy child with fever','A 4-year-old from Nyagatare has had high fevers and is now hard to wake.','Paediatrics','Infectious disease','Severe malaria',5,'hard','pediatrics',25,200,'both',false,null,null,64,
'{"name":"Keza M.","age":4,"sex":"Female","location":"Nyagatare"}',
'Keza, 4, is carried in by her mother. She has had fever for 3 days and today she has become very sleepy and had one fit at home.',
'[{"category":"Presenting complaint","questions":[{"id":"h1","q":"How long has she had fever?","a":"Three days, very hot at night."},{"id":"h2","q":"Tell me about the fit.","a":"Her whole body shook for about 5 minutes this morning."},{"id":"h3","q":"Is she eating and drinking?","a":"She refuses to drink since yesterday. Very little urine."}]},{"category":"Background","questions":[{"id":"h4","q":"Do you use a mosquito net?","a":"Our net is torn, we have not replaced it."},{"id":"h5","q":"Any vomiting or diarrhoea?","a":"She vomited twice today."},{"id":"h6","q":"Are her vaccines up to date?","a":"Yes, all done at the health centre."}]}]',
'[{"id":"e1","name":"Vital signs","finding":"T 39.6°C, HR 160, RR 44, SpO2 93%, capillary refill 4 seconds"},{"id":"e2","name":"Conscious level","finding":"Responds to pain only (Blantyre coma score 2)."},{"id":"e3","name":"General exam","finding":"Marked pallor, mild jaundice, dry mucous membranes."},{"id":"e4","name":"Abdomen","finding":"Spleen palpable 3 cm below the costal margin."}]',
'[{"id":"i1","name":"Malaria rapid test & blood film","result":"RDT positive. Film: P. falciparum, 8% parasitaemia."},{"id":"i2","name":"Blood glucose","result":"2.1 mmol/L"},{"id":"i3","name":"Full blood count","result":"Hb 5.2 g/dL, platelets 62 ×10⁹/L, WBC 11."},{"id":"i4","name":"Lumbar puncture","result":"Deferred — clinically unstable."},{"id":"i5","name":"Head CT","result":"No abnormality."}]',
'{"prompt":"Interpret the glucose and blood count together. What needs urgent correction?","investigation":"Blood glucose","options":["Hypoglycaemia and severe anaemia","Hyperglycaemia only","Low platelets only","Nothing urgent"]}',
'List your top three differential diagnoses.',
ARRAY['Severe (cerebral) malaria','Bacterial meningitis','Sepsis','Febrile seizure','Viral encephalitis'],
'Severe (cerebral) malaria',ARRAY['Severe (cerebral) malaria','Bacterial meningitis','Sepsis'],
'[{"id":"m1","label":"IV/IM artesunate immediately"},{"id":"m2","label":"Correct hypoglycaemia with IV dextrose"},{"id":"m3","label":"Transfuse blood for severe anaemia"},{"id":"m4","label":"Oral artemether-lumefantrine and send home"},{"id":"m5","label":"Protect airway, position and monitor for seizures"},{"id":"m6","label":"Large fluid boluses of 40 ml/kg"}]',
'{"prompt":"Keza''s mother is frightened and asks why this happened. What do you say?","options":[{"id":"c1","text":"\"This is a serious malaria infection. We have started strong medicine and are watching her closely. A new treated net will help protect your family.\""},{"id":"c2","text":"\"You should have brought her earlier.\""},{"id":"c3","text":"\"It''s just a fever, she will be fine.\""}]}',
'{"good":"Keza wakes after 24 hours, her glucose stays normal and she goes home on day 5.","partial":"She recovers slowly and needs a longer admission.","poor":"She has further seizures and needs intensive care transfer."}',
'{"summary":"Cerebral malaria with hypoglycaemia and severe anaemia in a young child.","teaching_points":["Any child with fever and reduced consciousness in an endemic area: think severe malaria.","Give parenteral artesunate first — do not wait for all tests.","Always check glucose in a drowsy or fitting child."],"pitfalls":["Treating severe malaria with oral tablets.","Aggressive fluid boluses in severe malaria."]}',
'{"key_history":["h1","h2","h3","h4"],"key_exams":["e1","e2","e3","e4"],"key_investigations":["i1","i2","i3"],"unnecessary_investigations":["i5"],"interpretation":"Hypoglycaemia and severe anaemia","management_correct":["m1","m2","m3","m5"],"management_harmful":["m4","m6"],"communication_best":"c1"}'),
('33333333-3333-4333-8333-333333333333','Sudden pelvic pain in a young woman','A 26-year-old teacher has sharp lower abdominal pain and felt faint at work.','Obstetrics & Gynaecology','Reproductive','Ectopic pregnancy',3,'easy','maternity',15,100,'solo',false,null,null,92,
'{"name":"Claudine U.","age":26,"sex":"Female","location":"Huye"}',
'Claudine, 26, arrives with sudden sharp pain low on the right side of her abdomen. She nearly fainted at school an hour ago.',
'[{"category":"Presenting complaint","questions":[{"id":"h1","q":"When was your last period?","a":"About 7 weeks ago. It is late."},{"id":"h2","q":"Any vaginal bleeding?","a":"A little dark spotting since yesterday."},{"id":"h3","q":"Does the pain go anywhere?","a":"Sometimes to my right shoulder tip."}]},{"category":"Background","questions":[{"id":"h4","q":"Any past pelvic infections?","a":"I was treated for a pelvic infection two years ago."},{"id":"h5","q":"Are you using contraception?","a":"No, not at the moment."}]}]',
'[{"id":"e1","name":"Vital signs","finding":"HR 112, BP 96/60, RR 20, T 36.9°C"},{"id":"e2","name":"Abdomen","finding":"Tender right iliac fossa with guarding."},{"id":"e3","name":"Speculum exam","finding":"Small amount of dark blood, cervical os closed."}]',
'[{"id":"i1","name":"Urine pregnancy test","result":"Positive."},{"id":"i2","name":"Pelvic ultrasound","result":"Empty uterus, right adnexal mass, free fluid in the pouch of Douglas."},{"id":"i3","name":"Full blood count & group and cross-match","result":"Hb 9.8 g/dL. Blood group O+."},{"id":"i4","name":"Abdominal CT","result":"Free fluid in the pelvis."}]',
'{"prompt":"What does the ultrasound most likely show?","investigation":"Pelvic ultrasound","options":["Ruptured ectopic pregnancy","Normal early pregnancy","Appendicitis","Ovarian cyst without pregnancy"]}',
'List your top three differential diagnoses.',
ARRAY['Ruptured ectopic pregnancy','Appendicitis','Miscarriage','Ruptured ovarian cyst','Pelvic inflammatory disease'],
'Ruptured ectopic pregnancy',ARRAY['Ruptured ectopic pregnancy','Miscarriage','Appendicitis'],
'[{"id":"m1","label":"Two large-bore IV lines and start fluid resuscitation"},{"id":"m2","label":"Urgent gynaecology review for surgery"},{"id":"m3","label":"Cross-match blood"},{"id":"m4","label":"Send home with painkillers and repeat test in 48 hours"},{"id":"m5","label":"Methotrexate as the only treatment"}]',
'{"prompt":"Claudine asks whether she will still be able to have children. What do you say?","options":[{"id":"c1","text":"\"No, this means you can''t have children.\""},{"id":"c2","text":"\"Many women go on to have healthy pregnancies after this. Our priority now is to stop the bleeding and keep you safe; we will talk about the future together afterwards.\""},{"id":"c3","text":"\"Let''s not talk about that now.\""}]}',
'{"good":"She has a laparoscopic salpingectomy within the hour and recovers well.","partial":"Surgery is delayed and she needs a blood transfusion.","poor":"She becomes shocked before theatre and needs emergency laparotomy."}',
'{"summary":"Ruptured right tubal ectopic pregnancy with haemodynamic compromise.","teaching_points":["Any woman of reproductive age with abdominal pain: do a pregnancy test.","Positive test + empty uterus + free fluid = ruptured ectopic until proven otherwise.","Unstable patients need resuscitation and surgery, not medical therapy."],"pitfalls":["Delaying surgery for a CT scan.","Discharging a tachycardic patient with a positive pregnancy test."]}',
'{"key_history":["h1","h2","h3","h4"],"key_exams":["e1","e2","e3"],"key_investigations":["i1","i2","i3"],"unnecessary_investigations":["i4"],"interpretation":"Ruptured ectopic pregnancy","management_correct":["m1","m2","m3"],"management_harmful":["m4","m5"],"communication_best":"c2"}');

